var _ = legs.CompatV1

// txWithRetryModelRows is what this package's model tier claims.
//
// Every row here needs sequences of calls judged against something
// outside the subject, which is what separates them from the rows
// above: those settle a claim with a fixed call sequence, and these
// cannot be stated that way at all. That is also why each takes the
// Subject rather than an instance — a sequence run builds its own, and
// some of them build two.
func txWithRetryModelRows() []suite.Check[TxWithRetry] {
	return []suite.Check[TxWithRetry]{
		{
			ID:    txWithRetryCheckIndex.Model.RespectsContext(),
			Class: suite.ClassLaws,
			Claim: "a lifecycle call handed an already-cancelled context reports the cancellation",
			Binds: []string{
				lawid.LifecycleRespectsContext,
			},
			Falsifiable: suite.Proven(),
			Strength:    suite.StrengthObserved,
			RunWith: func(tb testing.TB, sub suite.Subject[TxWithRetry]) {
				txWithRetryAssertRespectsContext(tb, sub)
			},
		},
	}
}

// --- TxWithRetry's model tier -------------------------------------------
//
// Random sequences of TxWithRetry's methods, run against every subject and
// something that judges them from outside. The rows on the run surface
// above carry it, and TxWithRetrySuite.Without declines any of them by name.
//
//	Reference: the subject's own factory — no reader/writer pair derives a store,
//	           so a second instance driven identically stands in: twins must
//	           agree, which catches nondeterminism and hidden shared state but
//	           not a subject wrong the same way twice; ref= raises the floor
//	Sequences: Begin (lifecycle), Commit (lifecycle), Rollback (lifecycle)
//	Not bound:
//	           AUTO-TRANSACTION-NO-MID-TX-VISIBILITY — observes through Begin, which answers nothing to observe
//	           AUTO-TWO-PHASE-MUTEX — observes through Begin, which answers nothing to observe
//	           AUTO-TWO-PHASE-ROLLBACK-AFTER-COMMIT — observes through Begin, which answers nothing to observe
//	           tx-with-retry differential — the reference is the subject's own factory, whose comparison already rides each law leg's actions; alone it catches nondeterminism and nothing a second instance shares
//
// txWithRetryModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func txWithRetryModelActions() []model.Action[TxWithRetry] {
	out := []model.Action[TxWithRetry]{
		action.Lifecycle("Begin",
			func(ctx context.Context, s txwithretry.TxWithRetry) error {
				return s.Begin(ctx)
			}),
		action.Lifecycle("Commit",
			func(ctx context.Context, s txwithretry.TxWithRetry) error {
				return s.Commit(ctx)
			}),
		action.Lifecycle("Rollback",
			func(ctx context.Context, s txwithretry.TxWithRetry) error {
				return s.Rollback(ctx)
			}),
	}
	return out
}

// txWithRetryAssertRespectsContext binds AUTO-LIFECYCLE-RESPECTS-CONTEXT over the shared sequences.
//
// One law, and the run's only oracle — see [legs.Law]
// for why the differential is off on every law leg.
func txWithRetryAssertRespectsContext(
	tb testing.TB,
	sub suite.Subject[TxWithRetry],
) {
	tb.Helper()

	buildRef, tier := legs.Reference(tb, sub, func() TxWithRetry { return sub.New(tb) })
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() TxWithRetry { return sub.New(tb) }, buildRef,
		txWithRetryModelActions(),
		[]law.Law[TxWithRetry]{
			law.LifecycleRespectsContext[txwithretry.TxWithRetry]{
				Op: func(ctx context.Context, s txwithretry.TxWithRetry) error {
					return s.Begin(ctx)
				},
				Name: "Begin",
			},
			law.LifecycleRespectsContext[txwithretry.TxWithRetry]{
				Op: func(ctx context.Context, s txwithretry.TxWithRetry) error {
					return s.Commit(ctx)
				},
				Name: "Commit",
			},
			law.LifecycleRespectsContext[txwithretry.TxWithRetry]{
				Op: func(ctx context.Context, s txwithretry.TxWithRetry) error {
					return s.Rollback(ctx)
				},
				Name: "Rollback",
			},
		})
}

